pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testRegression_property() public {
        vm.roll(1);
        address player = address(0x123);
        vm.deal(player, 10);
        vm.prank(player);
        bool ok;
        try c.play{value: 10}() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
        assertEq(c.pot(), 10);
    }
}
